def solve(workspace):
    n = workspace.length
    if n <= 1:
        return

    # Bubble sort to sort the array using only adjacent swaps.
    # Since there is no budget on swaps, O(n^2) is acceptable.
    for i in range(n - 1):
        for j in range(n - 1 - i):
            val_j = workspace.peek(j)
            val_j1 = workspace.peek(j + 1)
            if val_j > val_j1:
                workspace.swap_adjacent(j)
